#!/usr/bin/env node

// ────────────────────────────────────────────────────────────────
// DO NOT EDIT THIS FILE.
//
// COPY of source-of-truth at
//   ~/.claude/standards/scripts/verify/verify-api-first.mjs
//
// Local edits will be overwritten the next time
//   bash ~/.claude/standards/scripts/install-slice-gates.sh
// runs. Edit the ORIGINAL and re-install.
// ────────────────────────────────────────────────────────────────
/**
 * verify-api-first.mjs
 *
 * @version 1
 *
 * API_FIRST.yaml, mechanical: page-tier UI source is refused until the site is
 * mechanically complete — every flow E2E-mapped and mermaid-diagrammed, attested
 * in docs/site/MECHANICAL_COMPLETE.yaml.
 *
 * Green short-circuits: no page-tier source yet, or ui_discipline: none.
 * Checks when page-tier source exists:
 *   1. attestation file exists with the mechanical-complete marker
 *   2. every flows/*.flow.yaml stem in src is mapped in attestation.flows
 *   3. every mapped e2e contract path exists on disk
 *   4. every flow has a mermaid diagram (```mermaid in its .flow.md sibling,
 *      the flow yaml itself, or the feature's spec.md)
 *
 * Usage: node verify-api-first.mjs [<src-root>]   (default: src; repo root = cwd/../..)
 * Exit: 0 green, 1 red.
 */
import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const GREEN = "\x1b[32m";
const RED = "\x1b[31m";
const RESET = "\x1b[0m";
const NAME = "verify-api-first";
const SKIP = new Set(["node_modules", ".git", ".next", ".turbo", "dist", "build", "coverage", "out", ".archive"]);

function* walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) { if (!SKIP.has(e.name)) yield* walk(path.join(dir, e.name)); }
    else yield path.join(dir, e.name);
  }
}
const ok = (m) => { process.stdout.write(`${GREEN}✅ ${NAME}${RESET} — ${m}\n`); process.exit(0); };

const srcRoot = path.resolve(process.cwd(), process.argv[2] || "src");
if (!fs.existsSync(srcRoot)) ok("no src; nothing to verify.");

// ui_discipline short-circuit
for (const up of ["..", "../..", "../../.."]) {
  const auto = path.resolve(process.cwd(), up, ".standards", "autonomy.yaml");
  if (fs.existsSync(auto) && /^ui_discipline:\s*none\b/m.test(fs.readFileSync(auto, "utf8"))) ok("ui_discipline: none — API-first gate n/a.");
}

const files = [...walk(srcRoot)];

// page-tier present? (tier: page specs, or app/ route page files)
const pageTier = files.some((f) =>
  (f.endsWith("spec.yaml") && /^tier:\s*page\b/m.test(fs.readFileSync(f, "utf8"))) ||
  (/\/app\/.*page\.(tsx|jsx)$/.test(f) && !/\/app\/page\.(tsx|jsx)$/.test(f) === false) ||
  /\/app\/.*\/page\.(tsx|jsx)$/.test(f)
);
if (!pageTier) ok("no page-tier source yet — build APIs + flows first (API_FIRST.yaml).");

const violations = [];
const repoRoot = (() => {
  for (const up of [".", "..", "../.."]) {
    if (fs.existsSync(path.resolve(process.cwd(), up, ".git"))) return path.resolve(process.cwd(), up);
  }
  return path.resolve(process.cwd(), "../..");
})();
const attPath = path.join(repoRoot, "docs", "site", "MECHANICAL_COMPLETE.yaml");

const flowFiles = files.filter((f) => /\/flows\/[^/]+\.flow\.yaml$/.test(f));
const stems = flowFiles.map((f) => path.basename(f).replace(/\.flow\.yaml$/, ""));

if (!fs.existsSync(attPath)) {
  violations.push(`page-tier source exists but ${path.relative(repoRoot, attPath)} is missing — the mechanical site must be attested 100% before UI (API_FIRST.yaml)`);
} else {
  const att = fs.readFileSync(attPath, "utf8");
  if (!/mechanical-complete:\s*\d{4}-\d{2}-\d{2}\s+by:(user|agent)/.test(att)) {
    violations.push("attestation lacks the 'mechanical-complete: <date> by:(user|agent)' marker");
  }
  for (const stem of stems) {
    const m = att.match(new RegExp(`^\\s+${stem}:\\s*(\\S+)`, "m"));
    if (!m) { violations.push(`flow "${stem}" is not mapped in MECHANICAL_COMPLETE.yaml.flows — every flow must be E2E-mapped`); continue; }
    if (!fs.existsSync(path.join(repoRoot, m[1]))) violations.push(`flow "${stem}" maps to ${m[1]} which does not exist`);
  }
}

// mermaid per flow
for (const f of flowFiles) {
  const stem = path.basename(f).replace(/\.flow\.yaml$/, "");
  const candidates = [f, f.replace(/\.flow\.yaml$/, ".flow.md"), path.join(path.dirname(f), "..", "spec.md")];
  const hasMermaid = candidates.some((c) => fs.existsSync(c) && fs.readFileSync(c, "utf8").includes("```mermaid"));
  if (!hasMermaid) violations.push(`flow "${stem}" has no mermaid diagram (flow.md sibling, flow.yaml, or spec.md) — FLOW_CONTRACT.yaml.mermaid_required`);
}

if (violations.length === 0) ok(`page-tier permitted: ${stems.length} flow(s) attested E2E-mapped + diagrammed.`);
process.stderr.write(`${RED}❌ ${NAME}:${RESET} ${violations.length} violation(s)\n`);
for (const v of violations) process.stderr.write(`  ${v}\n`);
process.stderr.write("Per API_FIRST.yaml — the site must be 100% functional via APIs (flows E2E-green) before user-facing UI.\n");
process.exit(1);
